{
  "explanation": "If you invest $1 at 100% annual interest, compounding once a year gives you $2. Compounding n times a year gives (1 + 1/n)^n dollars. As n grows — monthly, daily, every second — this value climbs toward a limit of about $2.71828…, which is the number e. Continuous compounding is the mathematical ideal of interest growing at every instant.",
  "manimCode": "const title = new Text({ text: 'Compounding $1 at 100% interest', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.3, 0]);
scene.add(title);

const formula = new MathTex({ latex: '(1 + \\frac{1}{n})^{n} \\to e', color: WHITE });
await formula.waitForRender();
formula.moveTo([0, 2.5, 0]);
scene.add(formula);

const ax = new Axes({
  xRange: [1, 40, 5],
  yRange: [1.5, 3, 0.5],
  xLength: 9,
  yLength: 4,
  tips: false
});
ax.moveTo([0, -0.6, 0]);

const curve = ax.plot(n => Math.pow(1 + 1 / n, n), {
  color: BLUE,
  xRange: [1, 40],
  numSamples: 400
});

const eLine = new Polygon({
  vertices: [ax.c2p(1, Math.E), ax.c2p(40, Math.E)],
  color: YELLOW
});
eLine.setStrokeWidth(2).setFillOpacity(0);

const eLabel = new Text({ text: 'e ≈ 2.71828', color: YELLOW, fontSize: 22 });
eLabel.moveTo(ax.c2p(32, Math.E + 0.18));

scene.add(ax, curve, eLine, eLabel);

let nVal = 1;
const dot = new Dot({ point: ax.c2p(nVal, Math.pow(1 + 1 / nVal, nVal)), color: RED });
scene.add(dot);

let valueLabel = new Text({
  text: 'n = 1   →   $2.00000',
  color: WHITE,
  fontSize: 26
});
valueLabel.moveTo([0, -3.4, 0]);
scene.add(valueLabel);

function updateLabel(n) {
  const val = Math.pow(1 + 1 / n, n);
  const pos = valueLabel.getCenter();
  scene.remove(valueLabel);
  const nStr = Number.isInteger(n) ? String(n) : n.toFixed(1);
  valueLabel = new Text({
    text: 'n = ' + nStr + '   →   $' + val.toFixed(5),
    color: WHITE,
    fontSize: 26
  });
  valueLabel.moveTo(pos);
  scene.add(valueLabel);
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Compounds per year (n)',
  min: 1,
  max: 40,
  value: 1,
  step: 0.5,
  onChange: (v) => {
    nVal = v;
    const y = Math.pow(1 + 1 / nVal, nVal);
    dot.moveTo(ax.c2p(nVal, y));
    updateLabel(nVal);
  }
});

controls.addButton({
  label: 'Jump to continuous (e)',
  onClick: () => {
    nVal = 40;
    const y = Math.pow(1 + 1 / nVal, nVal);
    dot.moveTo(ax.c2p(nVal, y));
    updateLabel(nVal);
  }
});

await scene.wait(999999);"
}

